func summaryColumns(t *testing.T, commands []experimentalCommandInfo) []int {
	t.Helper()
	var cols []int
	for _, line := range strings.Split(renderExperimentalCommands(commands), "\n") {
		if line == "" {
			continue
		}
		info := indexOfSummary(t, line, commands)
		cols = append(cols, info)
	}
	return cols
}

